def _body_end(lines: list[str], definition_indexes: set[int]) -> int:
    index = len(lines)
    found = False
    while index > 0:
        previous = index - 1
        if previous in definition_indexes:
            found = True
        elif lines[previous].strip():
            break
        index -= 1
    return index if found else len(lines)


